def solve_Test(K):
    def is_neq_number(n):
        s = str(n)
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                return False
        return True

    count = 0
    num = 0
    while count < K:
        num += 1
        if is_neq_number(num):
            count += 1
    return num
